function leagueTargetLabel(s=season){const d=s.league.division;return d===1?'1부 상위 6위 · 6위 이내':S.divisionInfo({division:d-1,rules:'five-tier'}).name+' 승격 · 2위 이내';}
function leagueRulesLabel(s=season){const rule=S.promotionRules(s),count=S.leagueClubs(s).length;return [rule.promotion?'1~'+rule.promotion+'위 승격':'',rule.relegation?rule.relegationStart+'~'+count+'위 강등':'강등 없음',s.league.division===1?'1~2위 유럽 진출':''].filter(Boolean).join(' · ');}
function seasonHeadline(finished,me){if(finished){if(me.rank===1&&season.league.division===1)return '마침내, 1부의 정상에.';const move=S.movement(season);return move.kind==='promotion'?'한 계단 더 높은 무대로.':move.kind==='relegation'?'다시 올라갈 준비를.':'시즌은 끝나도 구단은 자란다.';}return season.league.division===5?'다섯 단계의 여정이 시작됩니다.':season.league.division===1?'이제, 강팀들의 무대로.':'구단 현황';}
function leagueZone(c){const d=season.league.division,rule=S.promotionRules(season);if(rule.promotion&&c.rank<=rule.promotion)return {kind:'promotion',label:'승격권'};if(rule.relegation&&c.rank>=rule.relegationStart)return {kind:'relegation',label:'강등권'};if(d===1&&c.rank===1)return {kind:'champion',label:'선두'};return null;}
function movementText(h){if(h.nextDivision<h.division)return S.divisionInfo({division:h.nextDivision,rules:'five-tier'}).name+' 승격';if(h.nextDivision>h.division)return S.divisionInfo({division:h.nextDivision,rules:'five-tier'}).name+' 강등';return h.division+'부 잔류';}
function renderDivision(table,me){
 const league=season.league,d=league.division,five=league.rules==='five-tier',top=d===1,bottom=five&&d===5,rounds=S.roundCount(season),clubCount=S.leagueClubs(season).length,finishedLeague=season.round===rounds,move=S.movement(season),rates=E.rates(season),previous=season.history.at(-1),rule=S.promotionRules(season),boundaryRank=top?rule.safeRank:2,boundary=table[boundaryRank-1],promotionName=d>1?S.divisionInfo({division:d-1,rules:league.rules}).name:'',relegationName=five&&d<5?S.divisionInfo({division:d+1,rules:league.rules}).name:'2부';
 const status=finishedLeague?(move.kind==='promotion'?promotionName+' 승격 확정':move.kind==='relegation'?relegationName+' 강등 확정':top&&me.rank===1?'1부 우승':d+'부 잔류'):!season.round?'첫 경기를 기다립니다.':top?(me.rank>=rule.relegationStart?'강등권 · 반등이 필요합니다.':me.rank===1?'현재 1부 선두.':'현재 잔류권.'):me.rank<=2?'현재 승격권.':'승격권을 향해.';
 const detail=finishedLeague?(!S.ready(season)?'남은 컵 일정을 마치면 다음 시즌으로 넘어갑니다.':'다음 시즌은 '+S.divisionInfo({division:move.to,rules:league.rules}).name+'에서 시작합니다.'):season.round?(top?'잔류선 '+rule.safeRank+'위':d===5?'승격선 2위':'승격선 2위 · '+(bottom?'강등 없음':'강등선 '+rule.relegationStart+'위'))+' '+boundary.points+'점 · 우리 구단 '+me.points+'점':top?'1부 '+rule.relegationStart+'~'+clubCount+'위는 다음 시즌 '+relegationName+'로 내려갑니다.':bottom?d+'부 1~2위는 다음 시즌 '+promotionName+'으로 올라갑니다.':d+'부 1~2위는 승격, '+rule.relegationStart+'~'+clubCount+'위는 강등됩니다.';
 const routeDivisions=five?[5,4,3,2,1]:[2,1],route=routeDivisions.map((division,index)=>{const info=S.divisionInfo({division,rules:league.rules}),active=division===d;return (index?'<span class="division-link" aria-hidden="true">›</span>':'')+'<div class="division-step '+(active?'active':'')+'"><span>리그 '+String(division).padStart(2,'0')+'</span><strong>'+info.name+'</strong><small>'+(division===1?'상위 무대':division===5?'1~2위 → '+S.divisionInfo({division:4,rules:'five-tier'}).name+' 승격':'1~2위 → '+S.divisionInfo({division:division-1,rules:league.rules}).name+' 승격')+'</small></div>';}).join('');
 $('league-journey').innerHTML=`<section class="division-panel" aria-label="승격과 강등"><div class="division-route ${five?'five-tier-route':''}">${route}</div><div class="division-status ${finishedLeague&&move.kind==='relegation'?'danger':''}"><div><span class="eyebrow">${finishedLeague?'이번 시즌의 도착점':'상위 리그로 가는 길'}</span><h2>${status}</h2><p>${detail}</p></div><div class="division-income"><span>${d}부 홈 경기 수입</span><b>${moneyLabel(rates.gateHome)}</b><small>+ 후원 ${moneyLabel(rates.sponsor)} / 경기</small></div></div>${previous?'<p class="division-recap">지난 시즌 · '+previous.division+'부 '+previous.rank+'위 · '+movementText(previous)+'</p>':''}<p class="division-footnote">${five?'5개 리그 · 총 116개 구단 · 현재 리그 '+clubCount+'팀':'각 리그 8개 구단'} · 홈과 원정 ${rounds}경기 · 현재 소속 리그의 컵 참가${five?' · 1부 1~2위는 챔피언스리그 진출':''}</p></section>`;
}
